er::class,'documents'])->name('documents'); Route::post('/dokumen',[PortalController::class,'storeDocument'])->middleware('role:super_admin,admin_pijar_suar')->name('documents.store'); Route::get('/bahan-mengajar/{submission}/tinjau',[PortalController::class,'reviewMaterial'])->middleware('role:super_admin,admin_pijar_suar')->name('materials.review'); Route::patch('/bahan-mengajar/{submission}/tinjau',[PortalController::class,'saveReview'])->middleware('role:super_admin,admin_pijar_suar')->name('materials.review.save'); });
